window.bookSummaryJSON = "<i>New York Times</i> best-selling author Christine Feehan titillates fans with sizzling romance, daring suspense, and blasts of paranormal intrigue. <i>Night Game</i> plunges Cajun GhostWalker Gator Fontenot into the sultry swamps of the Louisiana bayou as he tracks Flame, a beguiling redhead who possesses the same extraordinary physical and psychic powers. Sex and violence soon become dangerously entwined."; 
